function accountPanel(account, profile, tab) {
  if (tab === "activity") return `<section class="account-content-panel"><div class="account-content-heading"><span class="brand">YOUR SEVEN</span><h2>${escapeHTML(profile?.name || "Your")} activity</h2><p>Everything this profile has saved, watched, rated, or hidden.</p></div><div class="account-action-grid">${accountAction("◴", "Profile stats", "Watch time, streaks, genres, and completed titles", "data-profile-stats")}${accountAction("♥", "Favourites", `Movies and series saved by ${escapeHTML(profile?.name || "this profile")}`, "data-my-list")}${accountAction("▤", "Viewing activity", "Review or remove watched titles", "data-view-history")}${accountAction("★", "Your ratings", "Titles used to shape recommendations", "data-liked-titles", likedTitles().length || "View")}${accountAction("⊘", "Not for me", "Bring hidden titles back into browse rows", "data-hidden-titles", hiddenTitles().length || "View")}</div></section>`;
  if (tab === "playback") return `<section class="account-content-panel"><div class="account-content-heading"><span class="brand">PLAYBACK & ACCESS</span><h2>Viewing preferences</h2><p>These choices apply only to ${escapeHTML(profile?.name || "this profile")}.</p></div><div class="settings-stack"><label class="account-toggle"><span>Autoplay next episode<small>Continue series automatically when available</small></span><input type="checkbox" data-pref="autoplayNext" ${account.preferences.autoplayNext !== false ? "checked" : ""}><i></i></label><label class="account-toggle"><span>Cinematic intro<small>Play the SEVEN ident when the app opens</small></span><input type="checkbox" data-pref="introEnabled" ${account.preferences.introEnabled !== false ? "checked" : ""}><i></i></label><label class="account-toggle"><span>Autoplay spotlight<small>Rotate featured titles on Home</small></span><input type="checkbox" data-pref="autoplayPreviews" ${account.preferences.autoplayPreviews !== false ? "checked" : ""}><i></i></label><label class="account-toggle"><span>New episode alerts<small>Notify me when a show in Favourites has a new episode</small></span><input type="checkbox" data-pref="episodeAlerts" ${account.preferences.episodeAlerts === true ? "checked" : ""}><i></i></label><div class="account-selects"><label class="account-select">Maturity setting<select data-pref="maturity"><option ${account.preferences.maturity === "Kids" ? "selected" : ""}>Kids</option><option ${account.preferences.maturity === "13+" ? "selected" : ""}>13+</option><option ${account.preferences.maturity === "16+" ? "selected" : ""}>16+</option><option ${account.preferences.maturity === "18+" ? "selected" : ""}>18+</option></select></label><label class="account-select">Display language<select data-pref="language"><option ${account.preferences.language === "English" ? "selected" : ""}>English</option><option ${account.preferences.language === "Arabic" ? "selected" : ""}>Arabic</option><option ${account.preferences.language === "French" ? "selected" : ""}>French</option></select></label></div></div></section>`;
  if (tab === "security") return `<section class="account-content-panel"><div class="account-content-heading"><span class="brand">ACCOUNT & DEVICE</span><h2>Security and privacy</h2><p>Manage this device and your account credentials.</p></div><div class="account-security-layout"><div class="account-action-grid">${accountAction("⌁", "Change password", "Confirm your current password before setting a new one", "data-change-password", "Change")}${accountAction("⌂", "Install SEVEN", "Add SEVEN to this device’s Home Screen", "data-install-seven", "Install")}${accountAction("⌫", "Clear viewing history", `Remove activity for ${escapeHTML(profile?.name || "this profile")}`, "data-clear-history", "Clear")}${accountAction("↪", "Sign out", "End this device session", "data-signout", "Sign out")}</div></div></section>`;
  const profiles = account.profiles.map(item => `<div class="profile-card ${item.id === profile?.id ? "active" : ""}"><button data-select-profile="${item.id}">${profileAvatar(item)}<b>${escapeHTML(item.name)}</b><small>${item.kids ? "Kids" : "Standard"}</small></button><button class="profile-edit" data-edit-profile="${item.id}" aria-label="Edit ${escapeHTML(item.name)}">✎</button></div>`).join("");
  const profileAdd = account.profiles.length < 5 ? `<button class="profile-add" data-add-profile><span>+</span><b>Add profile</b></button>` : "";
  return `<section class="account-content-panel account-profiles-panel"><div class="account-content-heading"><span class="brand">PROFILES</span><h2>Who’s watching?</h2><p>Choose a profile, or edit its avatar, PIN, and maturity settings.</p></div><div class="profiles">${profiles}${profileAdd}</div></section>`;
}
function accountHub() {
  const account = { ...(state.account || defaultAccount()), preferences:currentPreferences() }, profile = currentProfile(), tab = state.accountTab || "profiles", navOpen = state.accountSidebarOpen !== false;
  return `${header()}<main class="account-page account-workspace-page"><div class="account-page-top"><button class="account-back" data-account-back>‹ Browse</button><div class="account-heading"><span class="brand">SEVEN ACCOUNT</span><h1>Account</h1><p>${escapeHTML(state.user?.email || "Signed in")}</p></div><div class="account-active-profile">${profileAvatar(profile)}<span><b>${escapeHTML(profile?.name || "Profile")}</b><small>Watching now</small></span></div></div><div class="account-workspace ${navOpen ? "nav-open" : "nav-closed"}"><aside class="account-sidebar" aria-label="Account categories"><button class="account-nav-toggle" data-toggle-account-nav aria-label="${navOpen ? "Collapse" : "Expand"} account categories">☰ <span>Categories</span></button><nav>${accountNavItem("profiles", "◉", "Profiles", tab)}${accountNavItem("activity", "▦", "Your SEVEN", tab)}${accountNavItem("playback", "▷", "Playback", tab)}${accountNavItem("security", "⌾", "Security", tab)}</nav></aside><div class="account-workspace-content">${accountPanel(account, profile, tab)}</div></div></main>`;
}
function showProfileEditor(id = "") {
  const existing = state.account.profiles.find(profile => profile.id === id);
  state.profileDraft = existing ? { ...existing } : { id:`profile-${Date.now()}`, name:"", color:PROFILE_COLORS[state.account.profiles.length % PROFILE_COLORS.length], kids:false };
  state.profileEditorIsNew = !existing;
  state.profileSettingsReturn = "account";
  state.route = "profile-settings"; scrollToTop(); render();
}
function profileCategoryRow(id, icon, title, detail) { return `<button class="profile-category-row" data-profile-category="${id}"><i aria-hidden="true">${icon}</i><span><b>${title}</b><small>${detail}</small></span><em>›</em></button>`; }
function profileSettingsHome(profile, isNew) { return `<section class="profile-settings-hub"><div class="profile-hub-hero"><button class="profile-hub-avatar" data-profile-category="profile" aria-label="Edit ${escapeHTML(profile.name || "profile")}">${profileAvatar(profile)}<i>✎</i></button><h2>${escapeHTML(profile.name || "New profile")}</h2><p>${profile.kids ? "Kids profile" : "Standard profile"}</p></div><div class="profile-category-list">${profileCategoryRow("profiles", "◎", "Manage profiles", "Add or edit who can watch")}${profileCategoryRow("profile", "◉", "Edit this profile", "Name and avatar")}${profileCategoryRow("family", "♧", "Family controls", "Maturity, title restrictions, and kids mode")}${profileCategoryRow("playback", "▷", "Playback", "Autoplay and episode alerts")}${profileCategoryRow("language", "A", "Language & display", "Language used throughout SEVEN")}${profileCategoryRow("activity", "▦", "Your SEVEN activity", "Stats, favourites, and viewing history")}${profileCategoryRow("security", "⌾", "Privacy & security", "Profile PIN, device, and account actions")}</div>${isNew ? `<p class="profile-hub-note">Finish your profile details, then save the first category you open.</p>` : ""}</section>`; }
