  if (category === "family") { const blocked = restrictedTitles(profile), parentCode = `<section class="profile-pin-card parent-access-card family-parent-code"><h2>Parent access code</h2><p>${state.account?.parentPinHash ? "This code opens account and profile settings only. It never locks the profile chooser." : "Set a code to protect account and profile settings without locking a profile."}</p><label class="profile-pin-field">${state.account?.parentPinHash ? "Change parent access code" : "Set parent access code"}<input name="parentPin" type="password" inputmode="numeric" autocomplete="new-password" pattern="[0-9]{4,8}" minlength="4" maxlength="8" placeholder="${state.account?.parentPinHash ? "Leave blank to keep current code" : "4–8 digits"}"></label>${state.account?.parentPinHash ? `<label class="profile-remove-pin"><input type="checkbox" name="removeParentPin"> Turn off parent access code</label>` : ""}</section>`; return `<form id="profile-settings-form"><section class="profile-detail-card family-controls"><span class="brand">FAMILY CONTROLS</span><label class="profile-mobile-row profile-mobile-toggle"><i aria-hidden="true">♙</i><span><b>Kids profile</b><small>Use child-friendly browsing and stricter content filtering.</small></span><input name="kids" type="checkbox" ${profile.kids ? "checked" : ""}><em></em></label><label class="profile-mobile-row profile-mobile-select"><i aria-hidden="true">◈</i><span><b>Maturity rating</b><small>Choose the highest rating this profile can browse.</small></span><select name="maturity"><option ${preferences.maturity === "Kids" ? "selected" : ""}>Kids</option><option ${preferences.maturity === "13+" ? "selected" : ""}>13+</option><option ${preferences.maturity === "16+" ? "selected" : ""}>16+</option><option ${preferences.maturity === "18+" ? "selected" : ""}>18+</option></select></label><label class="profile-mobile-row profile-mobile-toggle"><i aria-hidden="true">♥</i><span><b>Extra family-safe filtering</b><small>Hide intense crime, war, mystery, thriller, and horror titles.</small></span><input name="familySafe" type="checkbox" ${preferences.familySafe === true ? "checked" : ""}><em></em></label><label class="profile-mobile-row profile-mobile-toggle"><i aria-hidden="true">◐</i><span><b>Block scary titles</b><small>Hide horror, thriller, and mystery titles from browsing.</small></span><input name="blockScary" type="checkbox" ${preferences.blockScary === true ? "checked" : ""}><em></em></label><label class="profile-mobile-row profile-mobile-toggle"><i aria-hidden="true">⌕</i><span><b>Allow title search</b><small>Turn off search to keep this profile’s browsing simple.</small></span><input name="searchEnabled" type="checkbox" ${preferences.searchEnabled !== false ? "checked" : ""}><em></em></label>${parentCode}</section><section class="profile-detail-card family-restrictions"><span class="brand">TITLE RESTRICTIONS</span><h2>Block specific titles</h2><p>Blocked titles disappear from Home, search, collections, and catalogs for this profile.</p>${isNew ? `<p class="family-restriction-note">Create this profile before adding title restrictions.</p>` : `<label class="family-title-search">Find a title to block<span><input id="family-title-search" placeholder="Search titles" maxlength="80" autocomplete="off"><button type="button" data-family-search>Find</button></span></label><div class="family-title-results" id="family-title-results" hidden></div><div class="family-blocked-list">${blocked.length ? blocked.map(item => `<article><img src="${item.posterPath ? TMDB_IMAGE + escapeHTML(item.posterPath) : "/icon.svg"}" alt=""><span><b>${escapeHTML(item.title)}</b><small>${item.type === "tv" ? "Series" : "Movie"}</small></span><button type="button" data-unblock-title="${item.type}:${item.id}">Allow</button></article>`).join("") : `<small class="family-restriction-note">No titles are blocked on this profile.</small>`}</div>`}</section><p class="form-error profile-settings-error" id="profile-error"></p>${save}</form>`; }
