  if (category === "language") return `<form id="profile-settings-form"><section class="profile-detail-card"><span class="brand">LANGUAGE & DISPLAY</span><label class="profile-mobile-row profile-mobile-select"><i aria-hidden="true">A</i><span><b>Display language</b><small>Choose the language used throughout SEVEN.</small></span><select name="language"><option ${preferences.language === "English" ? "selected" : ""}>English</option><option ${preferences.language === "Arabic" ? "selected" : ""}>Arabic</option><option ${preferences.language === "French" ? "selected" : ""}>French</option></select></label></section>${save}</form>`;
